from abc import ABC, abstractmethod

# Abstraction interface
class MessageSender(ABC):
    @abstractmethod
    def send(self, recipient: str, text: str) -> None:
        pass

# Concrete implementation 1
class TwilioSMSSender(MessageSender):
    def send(self, recipient: str, text: str) -> None:
        print(f"[Twilio SMS] Sending to {recipient}: {text}")

# High-level module depends strictly on MessageSender abstraction
class AlertService:
    def __init__(self, sender: MessageSender):
        self.sender = sender

    def trigger_alert(self, user_phone: str, msg: str):
        self.sender.send(user_phone, msg)

