        self.queue.append(data) 

    # for popping an element based on custom max function 
    def max_pop(self, max_func): 
        max_val = self.queue[0]
        max_index = 0
        for i in range(len(self.queue)):
            if max_func(max_val, self.queue[i]) == self.queue[i]: 
